compile.workshop:
variables {
    global:
        0: a
        1: b
        2: c
        3: t
}

rule ("strings") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(t, Custom String("a \n{0}/{1}\r\nx {2}", Global.a, Global.b, Custom String("{0} 2.50\r\n0{1}", Global.c, If-Then-Else(Global.a, Custom String("y"), Custom String("")))));
        Set Global Variable(t, Custom String("{0}{0}{1}", Global.a, Global.b));
        Set Global Variable(t, Custom String("n 3.14 0 1234567.89"));
        Set Global Variable(t, Custom String("abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstu{0}", Custom String("vwxyz{0}tail-tail-tail-tail-tail-tail-tail", Global.a)));
    }
}

